"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["17502"],{97268(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>l,frontMatter:()=>p,contentTitle:()=>d,toc:()=>u,assets:()=>c});var a=JSON.parse('{"id":"nhcx/v1/api/adjudicator/endpoints/adjudicator-process-request","title":"Provider: make the dummy payer act on a request","description":"Makes the sandbox dummy payer, participant 1000003538@hcx, approve, reject or query a pre-authorisation or claim you have submitted, by correlation ID.","source":"@site/docs/nhcx/v1/api/adjudicator/endpoints/adjudicator-process-request.mdx","sourceDirName":"nhcx/v1/api/adjudicator/endpoints","slug":"/nhcx/v1/api/adjudicator/endpoints/adjudicator-process-request","permalink":"/docs/pr-48/docs/nhcx/v1/api/adjudicator/endpoints/adjudicator-process-request","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Provider: make the dummy payer act on a request","sidebar_label":"Provider: make the dummy payer act on a request","sidebar_class_name":"api-method api-method--post","description":"Makes the sandbox dummy payer, participant 1000003538@hcx, approve, reject or query a pre-authorisation or claim you have submitted, by correlation ID.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-adjudicator.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Overview","permalink":"/docs/pr-48/docs/nhcx/v1/api/adjudicator/"},"next":{"title":"Provider: make the dummy payer send a payment notice","permalink":"/docs/pr-48/docs/nhcx/v1/api/adjudicator/endpoints/adjudicator-paymentnotice-init"}}'),r=n(62540),o=n(43023),s=n(52563),i=JSON.parse('{"id":"adjudicator_process_request","module":"PMJAY adjudicator","moduleId":"adjudicator","kind":"operation","method":"POST","path":"/process/request","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/dummyhcxpayer","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/dummyhcxpayer","description":"Sandbox, Dummy payer."}],"summary":"Provider: make the dummy payer act on a request","title":"Provider: make the dummy payer act on a request","description":"Makes the sandbox dummy payer, participant `1000003538@hcx`, approve, reject or query a pre-authorisation or claim you have submitted, by correlation ID.\\n\\n### Business purpose\\n\\nThe sandbox hosts a payer that answers back, and this hook decides what it answers. It closes the loop on the first message a new integration sends. Whichever answer comes back proves the token works, the participant record is live, the exchange can reach the provider\'s address, the dummy payer could open the message, and the provider could read its reply.\\n\\n### When to use\\n\\nUse it in the sandbox only. It makes the dummy payer approve, reject or query a pre-authorisation or claim you sent it.\\n\\n### Preconditions\\n\\n- You sent a pre-authorisation or claim to the dummy payer and hold its correlation ID.\\n- Your callback address is registered and answers `202` within 30 seconds.\\n- A valid ABDM session token.\\n\\n### Postconditions\\n\\nThe decision arrives on your callback, for example `/v1/preauth/on_submit`, on the same correlation ID. A `Query` first sends you a communication request, which you answer on `/v1/communication/on_request`.\\n\\n### Common mistakes\\n\\n- Passing the correlation ID of a request not sent to the dummy payer.\\n- Waiting for a decision after a `Query` without answering the communication request.\\n- Reading the rejection of an empty test bundle as a failure. It is the expected answer.\\n\\n### Best practices\\n\\n- Test all three outcomes of each flow, not only approval.\\n- Make the callback handler idempotent, since the exchange retries a missed receipt.\\n- Keep this hook out of production code paths. It exists only in the sandbox.\\n\\n### Related scenario\\n\\nA new provider integration sends the empty bundle from its smoke test to the dummy payer on `/v1/preauth/submit` and gets 202. It posts this hook with `action` `Approve`, `method` `Preauth` and that request\'s correlation ID. A `ProtocolResponse` refusing the empty bundle lands on its `/v1/preauth/on_submit`, the handler answers 202, and the base framework is proven end to end.\\n\\n### Specification\\n\\nChapter [Building and sending a JWE](/docs/nhcx/v1/getting-started/building-and-sending-a-jwe) of the NHCX integration specification.","gateway":"nhcx","security":[{"name":"bearerAuth","type":"apiKey","in":"header","headerName":"bearer_auth","description":"Every NHCX call carries the access token from the session call in a header named `bearer_auth`, as the word `Bearer`, a space and the token. NHCX reads `bearer_auth`, not `Authorization`.","example":"Bearer <access token>","prefix":"Bearer "}],"headers":[],"pathParams":[],"queryParams":[],"body":[{"name":"action","type":"string","required":false,"description":"","encrypted":false},{"name":"method","type":"string","required":false,"description":"","encrypted":false},{"name":"correlationId","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"action":"Approve","method":"Preauth","correlationId":"<correlation id>"},"responses":[{"status":"200","description":"The answer arrives on your callback for the request\'s family, `/v1/preauth/on_submit` for a pre-authorisation, as a sealed `ClaimResponse` or as a `ProtocolResponse` carrying a refusal, on the correlation ID you sent.","synthesised":false,"fields":[]}],"tag":"Dummy payer APIs","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/dummyhcxpayer/process/request \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"action\\": \\"Approve\\",\\n  \\"method\\": \\"Preauth\\",\\n  \\"correlationId\\": \\"<correlation id>\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/dummyhcxpayer/process/request \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"action\\": \\"Approve\\",\\n  \\"method\\": \\"Preauth\\",\\n  \\"correlationId\\": \\"<correlation id>\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/dummyhcxpayer/process/request\\",\\n    headers={\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"action\\": \\"Approve\\",\\n        \\"method\\": \\"Preauth\\",\\n        \\"correlationId\\": \\"<correlation id>\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node.js","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/dummyhcxpayer/process/request\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"action\\": \\"Approve\\",\\n    \\"method\\": \\"Preauth\\",\\n    \\"correlationId\\": \\"<correlation id>\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"},{"id":"java","label":"Java","language":"java","code":"import java.net.URI;\\nimport java.net.http.HttpClient;\\nimport java.net.http.HttpRequest;\\nimport java.net.http.HttpResponse;\\n\\nHttpClient client = HttpClient.newHttpClient();\\nHttpRequest request = HttpRequest.newBuilder()\\n    .uri(URI.create(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/dummyhcxpayer/process/request\\"))\\n    .header(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n    .header(\\"Content-Type\\", \\"application/json\\")\\n    .method(\\"POST\\", HttpRequest.BodyPublishers.ofString(\\"\\"\\"\\n        {\\n            \\"action\\": \\"Approve\\",\\n            \\"method\\": \\"Preauth\\",\\n            \\"correlationId\\": \\"<correlation id>\\"\\n        }\\n        \\"\\"\\"))\\n    .build();\\n\\nHttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());\\nSystem.out.println(response.statusCode() + \\" \\" + response.body());"},{"id":"php","label":"PHP","language":"php","code":"<?php\\n\\n$ch = curl_init(\'https://apisbx.abdm.gov.in/pmjay/sbxhcx/dummyhcxpayer/process/request\');\\ncurl_setopt_array($ch, [\\n    CURLOPT_CUSTOMREQUEST => \'POST\',\\n    CURLOPT_RETURNTRANSFER => true,\\n    CURLOPT_HTTPHEADER => [\\n        \'bearer_auth: Bearer <access token>\',\\n        \'Content-Type: application/json\',\\n    ],\\n    CURLOPT_POSTFIELDS => <<<\'JSON\'\\n    {\\n        \\"action\\": \\"Approve\\",\\n        \\"method\\": \\"Preauth\\",\\n        \\"correlationId\\": \\"<correlation id>\\"\\n    }\\n    JSON,\\n]);\\n\\n$response = curl_exec($ch);\\necho curl_getinfo($ch, CURLINFO_HTTP_CODE), \' \', $response, PHP_EOL;"},{"id":"go","label":"Go","language":"go","code":"package main\\n\\nimport (\\n\\t\\"fmt\\"\\n\\t\\"io\\"\\n\\t\\"net/http\\"\\n\\t\\"strings\\"\\n)\\n\\nfunc main() {\\n\\tbody := strings.NewReader(`{\\n  \\"action\\": \\"Approve\\",\\n  \\"method\\": \\"Preauth\\",\\n  \\"correlationId\\": \\"<correlation id>\\"\\n}`)\\n\\treq, err := http.NewRequest(\\"POST\\", \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/dummyhcxpayer/process/request\\", body)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\treq.Header.Set(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n\\treq.Header.Set(\\"Content-Type\\", \\"application/json\\")\\n\\n\\tresp, err := http.DefaultClient.Do(req)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\tdefer resp.Body.Close()\\n\\tout, _ := io.ReadAll(resp.Body)\\n\\tfmt.Println(resp.StatusCode, string(out))\\n}"},{"id":"csharp","label":"C#","language":"csharp","code":"using var client = new HttpClient();\\nvar request = new HttpRequestMessage(new HttpMethod(\\"POST\\"), \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/dummyhcxpayer/process/request\\");\\nrequest.Headers.TryAddWithoutValidation(\\"bearer_auth\\", \\"Bearer <access token>\\");\\nrequest.Content = new StringContent(\\"\\"\\"\\n    {\\n        \\"action\\": \\"Approve\\",\\n        \\"method\\": \\"Preauth\\",\\n        \\"correlationId\\": \\"<correlation id>\\"\\n    }\\n    \\"\\"\\", System.Text.Encoding.UTF8, \\"application/json\\");\\n\\nvar response = await client.SendAsync(request);\\nConsole.WriteLine($\\"{(int)response.StatusCode} {await response.Content.ReadAsStringAsync()}\\");"},{"id":"ruby","label":"Ruby","language":"ruby","code":"require \'net/http\'\\n\\nuri = URI(\'https://apisbx.abdm.gov.in/pmjay/sbxhcx/dummyhcxpayer/process/request\')\\nrequest = Net::HTTP::Post.new(uri)\\nrequest[\'bearer_auth\'] = \'Bearer <access token>\'\\nrequest[\'Content-Type\'] = \'application/json\'\\nrequest.body = <<~\'JSON\'\\n  {\\n    \\"action\\": \\"Approve\\",\\n    \\"method\\": \\"Preauth\\",\\n    \\"correlationId\\": \\"<correlation id>\\"\\n  }\\nJSON\\n\\nresponse = Net::HTTP.start(uri.hostname, uri.port, use_ssl: uri.scheme == \'https\') do |http|\\n  http.request(request)\\nend\\nputs response.code, response.body"}]}');let p={title:"Provider: make the dummy payer act on a request",sidebar_label:"Provider: make the dummy payer act on a request",sidebar_class_name:"api-method api-method--post",description:"Makes the sandbox dummy payer, participant 1000003538@hcx, approve, reject or query a pre-authorisation or claim you have submitted, by correlation ID.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-adjudicator.yaml",generated:!0},d,c={},u=[];function h(e){return(0,r.jsx)(s.Ay,{operation:i})}function l(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(h,{...e})}):h(e)}}}]);